local out=peripheral.find("monitor") or term.current(); term.redirect(out); term.clear(); term.setCursorPos(1,1); local backend=(NEXUS_CONFIG and NEXUS_CONFIG.backend) or ""; if backend=="" then print("Browser backend not configured."); os.pullEvent(); return end
local function enc(s) return tostring(s):gsub("[^%w%-%._~]",function(c)return string.format("%%%02X",string.byte(c)) end) end
local function req(path) local h,e=http.get(backend..path,{["Accept"]="application/json"}); if not h then error(e or "HTTP request failed") end; local body=h.readAll(); h.close(); local ok,d=pcall(textutils.unserializeJSON,body); if not ok then error("Invalid JSON from backend") end; return d end
print("NEXUS BROWSER"); print("Backend: "..backend); print("Enter a URL or search phrase. Blank exits."); while true do write("nexus://web> "); local q=read(); if q=="" then break end; local ok,d=pcall(function() if q:match("^https?://") then return req("/fetch?url="..enc(q)) else return req("/search?q="..enc(q)) end end); if not ok then printError(d) elseif d.type=="search" then print("RESULTS"); for i,r in ipairs(d.results or {}) do print(i..") "..r.title); print("   "..r.url) end; else print("\n"..(d.title or "PAGE")); print(string.rep("-",40)); print(d.text or ""); print("\nLINKS"); for i,l in ipairs(d.links or {}) do print(i..") "..l.title.." -> "..l.url) end end end
